import React from "react";
import { auth, signIn, signOut } from "@/auth";

// Fetch the data from your FastAPI server
async function getDeals() {
  const res = await fetch('http://34.136.183.127:8000/api/deals', { cache: 'no-store' });
  if (!res.ok) return { deals: [] };
  return res.json();
}

export default async function Home() {
  // Check if the user is logged in
  const session = await auth();
  
  const data = await getDeals();
  const deals = data.deals || [];

  return (
    <main className="min-h-screen bg-gray-50 font-sans">
      {/* Top Navigation Bar */}
      <nav className="w-full bg-white shadow-sm px-8 py-4 flex justify-between items-center border-b border-gray-100">
        <h1 className="text-3xl font-black text-blue-900 tracking-tighter">think a trip</h1>
        
        <div>
          {session ? (
            <div className="flex items-center gap-4">
              <span className="text-sm font-semibold text-gray-600 bg-gray-100 px-3 py-1 rounded-full">
                {session.user?.email}
              </span>
              <form action={async () => { "use server"; await signOut(); }}>
                <button className="text-sm font-bold text-gray-500 hover:text-red-600 transition-colors">
                  Sign Out
                </button>
              </form>
            </div>
          ) : (
             <form action={async () => { "use server"; await signIn(); }}>
                <button className="bg-blue-600 hover:bg-blue-700 text-white px-6 py-2 rounded-full font-bold transition-all shadow-md">
                  Log In
                </button>
             </form>
          )}
        </div>
      </nav>

      {/* Main Deal Grid */}
      <div className="p-8 max-w-6xl mx-auto mt-8">
        <header className="mb-10">
          <h2 className="text-4xl font-extrabold text-gray-900">Live Global Escapes</h2>
          <p className="text-gray-500 mt-2 text-lg">The absolute cheapest outbound flights from India, updated daily.</p>
        </header>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {deals.map((deal: any) => (
            <div key={deal.flight_number} className="p-6 border border-gray-200 rounded-2xl shadow-sm bg-white hover:shadow-xl transition-all flex flex-col justify-between">
              <div>
                <span className="text-xs font-black text-blue-800 bg-blue-50 px-2 py-1 rounded uppercase tracking-widest mb-4 inline-block">
                  {deal.airline}
                </span>
                <h3 className="text-2xl font-black text-gray-800 tracking-tight">
                  {deal.origin} ➔ {deal.destination}
                </h3>
                <p className="text-xs text-gray-400 font-mono mt-1">FLIGHT: {deal.flight_number}</p>
              </div>
              
              <div className="mt-8 flex justify-between items-end border-t border-gray-100 pt-4">
                <p className="text-emerald-500 font-black text-3xl">{deal.price}</p>
                <button className="bg-gray-900 text-white text-sm font-bold px-4 py-2 rounded-lg hover:bg-black transition">
                  View
                </button>
              </div>
            </div>
          ))}
        </div>
      </div>
    </main>
  );
}
